package aimark

import (
	"bytes"
	"context"
	"crypto/ed25519"
	"encoding/base64"
	"errors"
	"strings"
	"testing"
	"time"

	"github.com/prometheus/client_golang/prometheus"

	"vornik.io/vornik/internal/persistence"
)

// GitHub #117: EU AI Act Art 50(2) marking (Art 50 design §14.7). A mark
// is a signed statement that the content with this SHA-256 was generated by
// an AI system operated with Vornik. These tests pin the signature and the
// encoding a third-party verifier relies on.

func testSigner(t *testing.T, b byte) *Signer {
	t.Helper()
	return NewSigner(bytes.Repeat([]byte{b}, ed25519.SeedSize))
}

func TestSignVerifyRoundTrip_117(t *testing.T) {
	s := testSigner(t, 1)
	compact, m, err := s.Sign(ForContent([]byte("hello"), "telegram", "2026.11.1", time.Unix(0, 0)))
	if err != nil {
		t.Fatal(err)
	}
	got, err := Verify(compact, s.Keys())
	if err != nil {
		t.Fatalf("a mark must verify with its own key: %v", err)
	}
	if got != m || got.SHA256 != "2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824" || got.Src != "trainedAlgorithmicMedia" {
		t.Fatalf("unexpected mark: %+v", got)
	}
}

func tamper(compact string, f func(payload []byte) []byte) string {
	p, sig, _ := strings.Cut(compact, ".")
	raw, _ := base64.RawURLEncoding.DecodeString(p)
	return base64.RawURLEncoding.EncodeToString(f(raw)) + "." + sig
}

func TestVerify_RefusesTamperedPayload_117(t *testing.T) {
	s := testSigner(t, 1)
	compact, _, _ := s.Sign(ForContent([]byte("hello"), "telegram", "2026.11.1", time.Unix(0, 0)))
	bad := tamper(compact, func(p []byte) []byte {
		return bytes.Replace(p, []byte(`"sha256":"2c`), []byte(`"sha256":"3c`), 1)
	})
	if _, err := Verify(bad, s.Keys()); err == nil {
		t.Fatal("a changed sha256 field must fail verification")
	}
	p, sig, _ := strings.Cut(compact, ".")
	b, _ := base64.RawURLEncoding.DecodeString(sig)
	b[0] ^= 1
	if _, err := Verify(p+"."+base64.RawURLEncoding.EncodeToString(b), s.Keys()); err == nil {
		t.Fatal("a changed signature must fail verification")
	}
}

func TestVerify_UnknownKeyFails_117(t *testing.T) {
	compact, _, _ := testSigner(t, 1).Sign(ForContent([]byte("x"), "email", "dev", time.Unix(0, 0)))
	if _, err := Verify(compact, testSigner(t, 2).Keys()); err == nil {
		t.Fatal("a mark signed by an unknown key must fail")
	}
}

// k1 retired, k2 current: marks of both verify (M4 rotation).
func TestVerify_RetiredAndCurrentKeys_117(t *testing.T) {
	k1, k2 := testSigner(t, 1), testSigner(t, 2)
	keys := Keys{}
	for kid, pub := range k1.Keys() {
		keys[kid] = pub
	}
	for kid, pub := range k2.Keys() {
		keys[kid] = pub
	}
	for _, s := range []*Signer{k1, k2} {
		compact, _, _ := s.Sign(ForContent([]byte("x"), "email", "dev", time.Unix(0, 0)))
		if _, err := Verify(compact, keys); err != nil {
			t.Errorf("kid %s: %v", s.KID(), err)
		}
	}
}

// The payload is the exact JSON a third-party verifier reads (§14.7 encoding).
func TestPayloadEncoding_117(t *testing.T) {
	s := testSigner(t, 1)
	compact, _, _ := s.Sign(ForContent([]byte("hello"), "telegram", "2026.11.1", time.Date(2026, 11, 1, 9, 0, 0, 0, time.UTC)))
	p, _, _ := strings.Cut(compact, ".")
	raw, err := base64.RawURLEncoding.DecodeString(p)
	if err != nil {
		t.Fatal(err)
	}
	want := `{"v":1,"gen":"vornik/2026.11.1","src":"trainedAlgorithmicMedia","sha256":"2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824","surface":"telegram","iat":"2026-11-01T09:00:00Z","kid":"` + s.KID() + `"}`
	if string(raw) != want {
		t.Fatalf("payload\n got %s\nwant %s", raw, want)
	}
	if strings.ContainsAny(compact, "=+/") {
		t.Fatal("both parts are unpadded base64url")
	}
}

type fakeLedger struct {
	err  error
	rows []persistence.AIOutputMark
	keys []persistence.AIMarkKey
}

func (f *fakeLedger) Record(_ context.Context, e persistence.AIOutputMark) error {
	if f.err != nil {
		return f.err
	}
	f.rows = append(f.rows, e)
	return nil
}

func (f *fakeLedger) RecordKey(_ context.Context, k persistence.AIMarkKey) error {
	f.keys = append(f.keys, k)
	return nil
}

func TestMarkerNew_RecordsTheLedgerRow_117(t *testing.T) {
	l := &fakeLedger{}
	m := NewMarker(testSigner(t, 1), l, func() string { return "2026.11.1" }, nil, nil)
	compact, mark, err := m.New(context.Background(), []byte("hello"), "email", "task-1")
	if err != nil {
		t.Fatal(err)
	}
	if len(l.rows) != 1 || l.rows[0].ContentSHA256 != mark.SHA256 || l.rows[0].Mark != compact || l.rows[0].TaskID != "task-1" {
		t.Fatalf("ledger row: %+v", l.rows)
	}
}

// A ledger failure must not withhold the reply: the signed mark comes back
// with the error, and the failure is counted.
func TestMarkerNew_LedgerFailureStillMarks_117(t *testing.T) {
	m := NewMarker(testSigner(t, 1), &fakeLedger{err: errors.New("db down")}, func() string { return "dev" }, nil, prometheus.NewRegistry())
	compact, _, err := m.New(context.Background(), []byte("hello"), "email", "")
	if err == nil || compact == "" {
		t.Fatalf("want a signed mark and the error, got %q, %v", compact, err)
	}
	if _, verr := Verify(compact, m.signer.Keys()); verr != nil {
		t.Fatalf("the returned mark must verify: %v", verr)
	}
	if m.LedgerErrors() != 1 {
		t.Fatalf("ledger errors counted: %d", m.LedgerErrors())
	}
}

// A verifier built from the persisted keys checks a mark after the signer
// (and the key it was derived from) is gone (review 3701 F2).
func TestKeysFrom_VerifiesAfterSignerIsGone_117(t *testing.T) {
	l := &fakeLedger{}
	s := testSigner(t, 1)
	if err := RegisterKey(context.Background(), l, s, time.Unix(0, 0)); err != nil {
		t.Fatal(err)
	}
	compact, _, _ := s.Sign(ForContent([]byte("x"), "email", "dev", time.Unix(0, 0)))
	if _, err := Verify(compact, KeysFrom(l.keys)); err != nil {
		t.Fatalf("a persisted key must verify an old mark: %v", err)
	}
}

// The public verifier receives arbitrary input: every malformed shape is an
// error, never a panic or a pass.
func TestVerify_MalformedInput_117(t *testing.T) {
	keys := testSigner(t, 1).Keys()
	good := b64.EncodeToString([]byte(`{"v":1}`))
	for _, in := range []string{"", "nodot", "!!!." + good, good + ".!!!", b64.EncodeToString([]byte("not json")) + "." + good} {
		if _, err := Verify(in, keys); err == nil {
			t.Errorf("%q must not verify", in)
		}
	}
}

// With no registerer, a ledger failure is still counted on the marker.
func TestMarkerNew_NoRegistererStillCounts_117(t *testing.T) {
	m := NewMarker(testSigner(t, 1), &fakeLedger{err: errors.New("down")}, func() string { return "dev" }, nil, nil)
	if _, _, err := m.New(context.Background(), []byte("x"), "email", ""); err == nil || m.LedgerErrors() != 1 {
		t.Fatalf("err %v, count %d", err, m.LedgerErrors())
	}
}

// The daemon learns its release after its servers (and so the marker) are
// built: the mark reads the release when it is made, not when the marker is
// (#117 step 2 wiring).
func TestMarker_ReadsTheReleaseWhenMarking(t *testing.T) {
	release := ""
	m := NewMarker(testSigner(t, 1), &fakeLedger{}, func() string { return release }, nil, nil)
	release = "2026.11.1"
	_, mark, err := m.New(context.Background(), []byte("x"), "s", "")
	if err != nil {
		t.Fatal(err)
	}
	if mark.Gen != "vornik/2026.11.1" {
		t.Fatalf("gen = %q, want the release at marking time", mark.Gen)
	}
}

// A download is marked from the artifact's stored hash, so the file is not
// read twice (#117 step 2 commit 1b): the mark equals New's for the same
// bytes, and a malformed hash is refused.
func TestMarker_NewForHashMatchesNew(t *testing.T) {
	l := &fakeLedger{}
	m := NewMarker(testSigner(t, 1), l, func() string { return "r" }, nil, nil)
	_, byContent, err := m.New(context.Background(), []byte("file bytes"), "download", "")
	if err != nil {
		t.Fatal(err)
	}
	_, byHash, err := m.NewForHash(context.Background(), byContent.SHA256, "download", "")
	if err != nil {
		t.Fatal(err)
	}
	if byHash.SHA256 != byContent.SHA256 || byHash.Surface != "download" {
		t.Fatalf("by hash %+v, by content %+v", byHash, byContent)
	}
	for _, bad := range []string{"", "xyz", strings.Repeat("A", 64), strings.Repeat("a", 63)} {
		if _, _, err := m.NewForHash(context.Background(), bad, "download", ""); err == nil {
			t.Errorf("hash %q accepted", bad)
		}
	}
}
